import{_ as a,o as r,c as t,a4 as o}from"./chunks/framework.BRzJ4ijD.js";const h=JSON.parse('{"title":"Quorum / W+R>N / Read Repair","description":"","frontmatter":{},"headers":[],"relativePath":"distributed/fault/quorum.md","filePath":"distributed/fault/quorum.md","lastUpdated":1788475713000}'),i={name:"distributed/fault/quorum.md"};function s(n,e,l,c,d,u){return r(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="quorum-w-r-n-read-repair" tabindex="-1">Quorum / W+R&gt;N / Read Repair <a class="header-anchor" href="#quorum-w-r-n-read-repair" aria-label="Permalink to &quot;Quorum / W+R&gt;N / Read Repair&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p><strong>Quorum 系统</strong>是 Dynamo / Cassandra / Riak / Voldemort / DynamoDB 等 leaderless AP 数据库的基础: 写要求 W replicas 确认, 读要求 R replicas 响应, <strong>W + R &gt; N</strong> 是保证 read quorum 与 write quorum overlap 的必要条件——但不是线性化的充分。 本章扫:</p><ol><li><strong>Quorum 公式与它的边界</strong>: W+R&gt;N、Cassandra 默认值、 LOCAL_QUORUM vs EACH_QUORUM。</li><li><strong>Sloppy Quorum + Hinted Handoff</strong>: 短期 outage 透写。</li><li><strong>Read Repair 贯量</strong>: coordinator 收 R 个响应, 推 newer 写给落后副本。</li><li><strong>Merkle Tree + Anti-Entropy Repair</strong>: 周期修复延迟。</li><li><strong>Strict quorum vs sloppy quorum</strong>, <strong>stale read 风险</strong> with non-strict quorum。</li><li><strong>典型 use case</strong>: DynamoDB RC vs Strong Read, Cassandra RackAware + LOCAL_QUORUM, Riak bucket property.</li></ol><hr><h2 id="一、quorum-系统形式化" tabindex="-1">一、Quorum 系统形式化 <a class="header-anchor" href="#一、quorum-系统形式化" aria-label="Permalink to &quot;一、Quorum 系统形式化&quot;">​</a></h2><h3 id="n-r-w" tabindex="-1">N, R, W <a class="header-anchor" href="#n-r-w" aria-label="Permalink to &quot;N, R, W&quot;">​</a></h3><ul><li>N: 每个 key 的 replica count (replication factor)</li><li>W: write consistency level, <strong>W replicas</strong> ack write 才算 commit</li><li>R: read consistency level, <strong>R replicas</strong> 响应 read</li></ul><h3 id="公式推论" tabindex="-1">公式推论 <a class="header-anchor" href="#公式推论" aria-label="Permalink to &quot;公式推论&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>W + R &gt; N  ⇒  read quorum 与 write quorum 必 overlap (至少 1 node) ⇒ read 看到最新 written value</span></span>
<span class="line"><span>N = 3, W = 2, R = 2 ⇒ overlap ≥ 1, stale-proof within sync replicas</span></span>
<span class="line"><span>N = 3, W = 1, R = 1 ⇒ overlap 可能 = 0, read 未必见最新写入</span></span>
<span class="line"><span>N = 3, W = 3, R = 1 ⇒ write 全副本持久, 单 read 不需 quorum 检查 (但慢, 任一 replica 慢 → write wait)</span></span>
<span class="line"><span>N = 5, W = 3, R = 3 ⇒ &quot;majority&quot; 与 &quot;majority&quot; 重叠 ≥ 1</span></span>
<span class="line"><span>N = 5, W = 2, R = 3 ⇒ 一般不推荐 (write 太弱, 任何 write 被节点副本完 ack 因 prefix check 压 缩 correctness)</span></span></code></pre></div><h3 id="w-r-n-是必要非充分条件" tabindex="-1">W+R&gt;N 是必要非充分条件 <a class="header-anchor" href="#w-r-n-是必要非充分条件" aria-label="Permalink to &quot;W+R&gt;N 是必要非充分条件&quot;">​</a></h3><p>W+R&gt;N 保 &quot;quorum overlap&quot; — 即 read 至少有一个副本看过那 write。 但 read 拿 raw value 后, coordinator 比较 R 副本返回的 timestamps/version:</p><ul><li>若 R 个副本都不一致 → coordinator 用最新 value reply + 触发 read repair.</li><li>若 R 误选 stalest quorum → 与 prior write quorum 不 overlap → coordinator 看到的全是 stale value。</li></ul><p>修复: extend read 传入 <strong>timestamps filter</strong> — 协调器 push quorum fingerprint query 况 → 客 client指定 replicated quorum. 二者 cross-DC <code>LOCAL_QUORUM</code> 加 extend read 不 cross-DC resolve.</p><h3 id="strict-quorum" tabindex="-1">Strict Quorum <a class="header-anchor" href="#strict-quorum" aria-label="Permalink to &quot;Strict Quorum&quot;">​</a></h3><p>Strict quorum 系统要求 read 必有 stale 修复 — coordinator 选 reads:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RESP_quorum = R replicas (含 newest known)</span></span>
<span class="line"><span>if not all synced:</span></span>
<span class="line"><span>    trigger async read_repair</span></span>
<span class="line"><span>    return newest</span></span></code></pre></div><ul><li>总 max believability 与 coordinator 完全 understandcost.</li><li>If staleness 加做 structural: read_lease 您 leader 新 leader 上更新版 → 协议 laffers fall well probabilistic.</li></ul><hr><h2 id="二、cassandra-consistency-levels" tabindex="-1">二、Cassandra Consistency Levels <a class="header-anchor" href="#二、cassandra-consistency-levels" aria-label="Permalink to &quot;二、Cassandra Consistency Levels&quot;">​</a></h2><p>Cassandra CQL 支持 per-query consistent level:</p><table tabindex="0"><thead><tr><th>Level</th><th>解释</th></tr></thead><tbody><tr><td><code>ANY</code></td><td>任意一个节点 (含 hinted handoff) ack 即可</td></tr><tr><td><code>ONE</code></td><td>单个 closest replica ack</td></tr><tr><td><code>TWO</code> / <code>THREE</code></td><td>2 / 3 个最近 replicas ack</td></tr><tr><td><code>LOCAL_ONE</code></td><td>local DC 1 个 replica</td></tr><tr><td><code>QUORUM</code></td><td>majority N/2+1 across all nodes</td></tr><tr><td><code>LOCAL_QUORUM</code></td><td>majority within local DC</td></tr><tr><td><code>EACH_QUORUM</code></td><td>each DC 各 quorum 强一致 (跨 DC 强 一)</td></tr><tr><td><code>ALL</code></td><td>all N replicas ack</td></tr></tbody></table><h3 id="local-quorum" tabindex="-1">LOCAL_QUORUM <a class="header-anchor" href="#local-quorum" aria-label="Permalink to &quot;LOCAL_QUORUM&quot;">​</a></h3><p>跨 DC 部署最常用:</p><ul><li>coordinator local DC reach majority quorum ⇒ reply client fast (~5ms P50)</li><li>cross-DC async replication 后 happen_NEXT隊 converge</li></ul><p>不保 cross-DC 同时 fail → 提供一致 fallback.</p><h3 id="each-quorum" tabindex="-1">EACH_QUORUM <a class="header-anchor" href="#each-quorum" aria-label="Permalink to &quot;EACH_QUORUM&quot;">​</a></h3><p>跨 DC 强一致: 每 DC 各 majority quorum acked 在 commit. latency = cross-DC RTT (~100-500ms). rare 用, 但 high-stakes session application useful.</p><h3 id="all" tabindex="-1">ALL <a class="header-anchor" href="#all" aria-label="Permalink to &quot;ALL&quot;">​</a></h3><p>最严格一致 + high latency. fail = 1 replica 全障 → write 失败. Rpo = 0, RTO ≈ 0.</p><h3 id="cassandra-默认" tabindex="-1">Cassandra 默认 <a class="header-anchor" href="#cassandra-默认" aria-label="Permalink to &quot;Cassandra 默认&quot;">​</a></h3><p>Cassandra driver 默认 LOCAL_ONE (low latency, eventually consistent)。 用户 read 用 LOCAL_QUORUM 大致 与 write LOCAL_QUORUM W+R&gt;N 保 staleness high。</p><hr><h2 id="三、dynamodb-consistency" tabindex="-1">三、DynamoDB Consistency <a class="header-anchor" href="#三、dynamodb-consistency" aria-label="Permalink to &quot;三、DynamoDB Consistency&quot;">​</a></h2><p>DynamoDB (AWS) 2007 Dynamo paper 派生。 DynamoDB operations support:</p><ul><li><strong>Eventually Consistent Read</strong>: default; 高 throughput + low latency + ∼1s 可能 stale。</li><li><strong>Strongly Consistent Read, <code>consistent=true</code> parameter in SDK</strong>; <code>R = ⌈N/2⌉ + 1</code>, priority 副本读 read_quorum检查 newer copy, 强制 stale &lt; 0.5s。</li><li><strong>Conditional Writes</strong> (<code>ConditionExpression</code>): opt-in CAS check via metadata table or special object level locks.</li></ul><p>DynamoDB 默认 N=3 跨 AZ 跨 machines in real AZ. 何时 consistent, 何 read 性 drop。PRO Production SLA:</p><ul><li>Eventually Consistent read: P99 &lt; 10ms</li><li>Strong Consistent read: P99 &lt; 20ms</li><li>Write: P99 &lt; 10ms</li></ul><hr><h2 id="四、read-repair-回顾" tabindex="-1">四、Read Repair 回顾 <a class="header-anchor" href="#四、read-repair-回顾" aria-label="Permalink to &quot;四、Read Repair 回顾&quot;">​</a></h2><p>(对照 <a href="./../replication/repair">repair.md</a> 详细描述。)</p><p><strong>Quorum + Read Repair 配合</strong>:</p><ol><li>coordinator read R 副本</li><li>比较 timestamps + 选 newest</li><li>后台 async push newest → 落后副本</li></ol><p><strong>风险</strong>: 若 (R=1) configured, read 不会接触 stalest 副本, read repair 不触发。 可以<strong>调大 R</strong> 让 read repair 更频繁。 同时 anti-entropy backup 修复 cold key。</p><hr><h2 id="五、sloppy-quorum-hinted-handoff" tabindex="-1">五、Sloppy Quorum + Hinted Handoff <a class="header-anchor" href="#五、sloppy-quorum-hinted-handoff" aria-label="Permalink to &quot;五、Sloppy Quorum + Hinted Handoff&quot;">​</a></h2><p>定义: write 在 -多 slaves responsense → quorum strict √ W 云 ramp. 依然 accept? quorum W. However if many replica unavailable -&gt; fallsloppy:</p><ul><li>choose live replacement replica + ring&#39;s next node with hinted_handff (handoft substantially quirks)</li></ul><p><strong>Use case</strong>: rolling restart时分 cluster, support 进行 operations. RPO grace 在 hint window (~1-3 hours)。</p><p>风险: sloppy quorum 不保 W+R&gt;N ⇒ read 可能拿到 stalest (replacement replica has 提 hint 但 not yet forwarded)。 认真业务 use case 用 <code>LOCAL_SERIAL</code> serialization = Paxos-on-row, consistency trade cost.</p><hr><h2 id="六、strong-consistency-for-quorum-systems" tabindex="-1">六、Strong Consistency for Quorum Systems <a class="header-anchor" href="#六、strong-consistency-for-quorum-systems" aria-label="Permalink to &quot;六、Strong Consistency for Quorum Systems&quot;">​</a></h2><p>Dynamo 等 AP quorum 系统不本质上 linearizable—</p><ol><li><strong>Non-linear: write 后 may &quot;toasted&quot; if read goes to stalest replica</strong> (W=2 WASN&#39;T read see ALL K reads 遇quar replica exact write) eventually consistent.</li><li><strong>Reading compare timestamps</strong>典型 LWW 写 → solve明明 race LWW.</li><li><strong>Cassandra Lightweight Transactions (LWT)</strong> = 4 phase Paxos + global cluster → linearizable.</li></ol><p>quote linearizability 与 quorum 跨不一定 同 level dimension. Quorum 保 both freshness + availability of financial takes via class mechanisms without 全 leaderless.</p><hr><h2 id="七、merkle-tree-anti-entropy-repair" tabindex="-1">七、Merkle Tree Anti-Entropy Repair <a class="header-anchor" href="#七、merkle-tree-anti-entropy-repair" aria-label="Permalink to &quot;七、Merkle Tree Anti-Entropy Repair&quot;">​</a></h2><p>(详细见 <a href="./../replication/repair">repair.md</a>.)</p><p>Quorum 系统一般提 <em><em>daily / weekly</em></em> summary++</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>anti_entropy_period: 10 days</span></span>
<span class="line"><span>incremental_repair_cycle_halfweek (event triggered)</span></span></code></pre></div><p>periodic 算 merkle_tree per token范围 + cross node diff + stream repair.</p><hr><h2 id="八、典型事故" tabindex="-1">八、典型事故 <a class="header-anchor" href="#八、典型事故" aria-label="Permalink to &quot;八、典型事故&quot;">​</a></h2><h3 id="cassandra-lww-clock-skew-lost-write" tabindex="-1">Cassandra LWW Clock Skew Lost Write <a class="header-anchor" href="#cassandra-lww-clock-skew-lost-write" aria-label="Permalink to &quot;Cassandra LWW Clock Skew Lost Write&quot;">​</a></h3><p>某用户 1 node NTP drift 5s, writes clients 过 系统接受 timestamp (P), ultimately metastability prevail 老补复制 W size 接受 daemon &quot;fail_over trigger after 14 days&quot; due boot. <strong>Fix</strong>: driver ensure monotonically increasing timestamp internally (driver server map memp), 不是 native now().</p><h3 id="riak-w-1-r-1-stale-policy-故障" tabindex="-1">Riak W=1 R=1 Stale Policy 故障 <a class="header-anchor" href="#riak-w-1-r-1-stale-policy-故障" aria-label="Permalink to &quot;Riak W=1 R=1 Stale Policy 故障&quot;">​</a></h3><p>某 Riak cluster buckets default option.fail with -- buckets, We 社写 1 sync asynchronous 副本. Post-reply within last read 显 stale 责. OPS Fix: 副本达标 W = (N/2)+1.</p><h3 id="mongodb-writeconcern-majority-不-linearizable" tabindex="-1">MongoDB WriteConcern=majority 不 = linearizable <a class="header-anchor" href="#mongodb-writeconcern-majority-不-linearizable" aria-label="Permalink to &quot;MongoDB WriteConcern=majority 不 = linearizable&quot;">​</a></h3><p>MongoDB replica set <code>w=&quot;majority&quot;</code> 提折 &quot;the majority 已 ACK 知知 the entry&quot;, 但 不 write journal fsync 完. 鸿沟 在 6.0 森 senior recommended <code>w=&quot;majority&quot;, j=&quot;true&quot;</code> give guarantee fsync durable. 没 <code>j=true</code>: 可能 leader crash 后 majority 已 ACK 但 commitlog 不 durably persist → durability loss.</p><hr><h2 id="九、易错清单" tabindex="-1">九、易错清单 <a class="header-anchor" href="#九、易错清单" aria-label="Permalink to &quot;九、易错清单&quot;">​</a></h2><ol><li><strong>W+R&gt;N ≠ linearizability</strong>: 它 保 quorum overlap so freshest 可显 但 仍然 race (just ephemeral staleness*) → 100% linearizability 相同方案重.</li><li><strong>LWW clock skew</strong>: 系统必须 trust clock 或 use HLC / vclock + driver monotonic. NTP drift 可 跨 5s。 HLC native on CockroachDB/YugaByte SQL database servers.</li><li><strong>Anti-Entropy 是 must, 不是 optional</strong>: cold-key 仅靠 read repair 不足. 周期 repair 与监控(monitor execution报) crucial.</li><li><strong>Sloppy Quorum 与 strict 写区别</strong>: <code>W=ANY</code> accepts hint replicas but R&gt;W can miss fresh write, so legitimately的生产 use case 谨慎.</li><li><strong>MongoDB <code>j=true</code></strong>: <code>w=majority</code> 仅指 mmap-in-write backlog, <code>j=true</code> file fsync to disk. 基本 durability 要求.</li><li><strong><code>LOCAL_QUORUM</code> 默认有用</strong>: 但 单 DC 跨 region partition 时 不能 数据 持续. 考 EACH_QUORUM 必要 if灾难性 cross-DC partition 亦需要 linearizable commit .</li><li><strong>R+W&gt;N 与 cross-tier 但 跨 DC no caching</strong>: <code>LOCAL_QUORUM</code> only-quorum in LC+local DC, 但其他 DC copy completely 异. 不 cross-DC strictly find cycle ensure RPO small.</li><li><strong>lineage consistency fault Casptum thropts</strong>: \`fail体育读 交易 Перед transaction never in management in major sorft datacenter dispatch LWT 全道 4 RTT 与 集群 中心 in datacenter ⇒ microsecond to fixed latency 不 provide.</li></ol><hr><h2 id="十、这一章带走的东西" tabindex="-1">十、这一章带走的东西 <a class="header-anchor" href="#十、这一章带走的东西" aria-label="Permalink to &quot;十、这一章带走的东西&quot;">​</a></h2><ol><li>W+R&gt;N 是 read/write quorum overlap 必要条件, 但不 linearizability 充分. R=quorum 可以拿 stalest quorum 曲, 不 consensistance with newest versions including &quot;latency&quot; delay.</li><li>Cassandra per-query CL 可调: LOCAL_ONE / LOCAL_QUORUM / EACH_QUORUM / ALL = consistency vs latency trade-off spectrum.</li><li>DynamoDB Strong consistent read = R = ⌈N/2⌉ + 1 = quorum read, 否则 EC.</li><li>Read Repair + Anti-Entropy 混合 must: high-frequency cold hot path 修复热 key, cyclic修理冷.</li><li>Sloppy Quorum / Hinted Handoff 短期 outage graceful. Hint-门至 typically 1-3 小时, longer-enc partitions 使用 anti-entropy.</li><li>LWW clock skew 写丢失 = 真正 industrial the accident, business critical data must use client_monotonic timestamp or HLC.</li><li>MongoDB w=majority ≠ durability without j=true + restart durable journaling. 这是见到 MongoDB operations. R+R data 呢 greatly different.</li></ol><hr><p>下一节 → <a href="./erasure">Erasure coding / Reed-Solomon</a></p>`,77)])])}const m=a(i,[["render",s]]);export{h as __pageData,m as default};
